import json,numpy as np,torch
import torch.nn.functional as F
from run_bilin18_l17_local_residual_charts import ROOT,ART,load_full_model
@torch.inference_mode()
def main():
 torch.set_num_threads(6);j=json.loads((ART/'bilin18_l17_output_metric_cross.json').read_text());model=load_full_model('cuda');model.lm_head.float();W=model.lm_head.weight.double();z=np.load(ART/'bilin18_l17_output_metric_cross_rows.npz');v=torch.tensor(z['responses'][:,0],device='cuda');s=np.load(ART/'bilin18_l17_recipient_tail_diagnostic_current_states.npz');st=torch.tensor(s['state'][797],device='cuda');base=torch.tensor(s['base'][797],device='cuda');lp=(30*torch.tanh(base.double()@W.T/30)).log_softmax(-1);lt=(30*torch.tanh(F.rms_norm(st+v,(1152,)).double()@W.T/30)).log_softmax(-1);p=lt.exp();mean=p.mean(0);lm=mean.log();total=(p*(lt-lp)).sum(-1).mean();coherent=(mean*(lm-lp)).sum();disp=(p*(lt-lm)).sum(-1).mean();res={'scope':'Post-selection decomposition over the fixed48 original-norm tail responses. Does not infer semantic meaning.','mean_individual_KL':float(total),'KL_mean_prediction_to_baseline':float(coherent),'mean_KL_individual_to_mean_prediction':float(disp),'closure_error':float(abs(total-coherent-disp)),'dispersion_fraction':float(disp/total),'token_ian_probability_quantiles':np.quantile(p[:,666].cpu().numpy(),[0,.25,.5,.75,1]).tolist()};assert res['closure_error']<1e-10;assert abs(float(total)-j['token_diagnostics'][0]['matched_origin_mean_KL'])<1e-8;(ART/'bilin18_l17_tail_token_dispersion.json').write_text(json.dumps(res,indent=2)+'\n');print(res)
if __name__=='__main__':main()
